changeSet.sql:
ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_tipo CHECK (
    notification_type IN ('NEW_INCIDENT_ALERT','STATUS_CHANGE_ALERT','CREDENTIAL_ISSUED','PASSWORD_RESET')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_status CHECK (
    status IN ('PENDIENTE','ENVIANDO','ENVIADO','FALLIDO','DESCARTADO','SUPRIMIDO')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_attempt_count CHECK (
    attempt_count >= 0
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_max_attempts CHECK (
    max_attempts >= 1
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_intentos CHECK (
    attempt_count <= max_attempts
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_motivo_sup CHECK (
    suppression_reason_code IN ('USUARIO_DESACTIVADO','SIN_CORREO','DESTINATARIO_NO_RESOLUBLE','NO_RECIPIENTS','COMPOSICION_INCOMPLETA')
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_enviado CHECK (
    status <> 'ENVIADO' OR (message_id IS NOT NULL AND sent_at IS NOT NULL)
)

ALTER TABLE aviso_correo ADD CONSTRAINT ck_aviso_correo_locked CHECK (
    status = 'ENVIANDO' OR locked_by IS NULL
)

DECLARE
    v_usuario  NUMBER;
    v_aviso_1  VARCHAR2(36 CHAR);
    v_aviso_2  VARCHAR2(36 CHAR);
    v_status   VARCHAR2(20 CHAR);
    v_intentos NUMBER;
    v_tope     NUMBER;
    v_filas    NUMBER;
    v_sqlcode  NUMBER := 0;

    c_clave  CONSTANT VARCHAR2(120 CHAR) := 'ORACULO-TSK057|STATUS_CHANGE_ALERT|42|7';
    c_nombre CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-057 Reportante';
    c_correo CONSTANT VARCHAR2(254 CHAR) := 'oraculo.tsk057.idem@example.invalid';
    c_asunto CONSTANT VARCHAR2(255 CHAR) := 'Credencial emitida (oraculo TSK-057)';
    c_cuerpo CONSTANT VARCHAR2(200 CHAR) := 'Cuerpo congelado del oraculo TSK-057.';

    -- Semilla idempotente del catalogo de clave fija que necesita el escenario. El display_order
    -- queda fuera del rango de las semillas reales para que no se confunda con ellas.
    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 971);

    -- username, password_hash y password_algorithm son NOT NULL sin default desde
    -- 06-usuario-credenciales.xml, y ux_usuario_username_ci exige un username distinto por cuenta.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_nombre, c_correo, 'oraculo.tsk057.idem', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-idem', 'argon2id')
      RETURNING user_id INTO v_usuario;

    -- El identificador del aviso lo genera el emisor (VARCHAR2(36)): SYS_GUID en hexadecimal
    -- minuscula ocupa 32 caracteres y cabe de sobra. SYS_GUID es funcion de SQL y se invoca
    -- con un SELECT ... FROM dual, igual que STANDARD_HASH en el oraculo de TSK-056.
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_1 FROM dual;

    -- Primer encolado. status se deja SIN INFORMAR a proposito: lo que se verifica despues es
    -- precisamente el DEFAULT de la columna, no un valor escrito por el cliente.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text)
         VALUES (v_aviso_1, c_clave, 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo);

    -- ---------------------------------------------------------------------------------
    -- Comprobacion 1 (AC-AVI-01): la solicitud nace PENDIENTE, con 0 intentos y tope 3,
    -- y se lee DE LA TABLA, no de las variables del escenario
    -- ---------------------------------------------------------------------------------
    SELECT status, attempt_count, max_attempts
      INTO v_status, v_intentos, v_tope
      FROM aviso_correo
     WHERE notification_id = v_aviso_1;

    IF v_status <> 'PENDIENTE' THEN
        RAISE_APPLICATION_ERROR(-20990, 'ORACULO TSK-057 / AC-AVI-01: el aviso recien encolado deberia nacer en estado PENDIENTE sin que la aplicacion lo informe, y ha nacido en ' || v_status);
    END IF;

    IF v_intentos <> 0 OR v_tope <> 3 THEN
        RAISE_APPLICATION_ERROR(-20990, 'ORACULO TSK-057 / AC-AVI-01: el aviso recien encolado deberia nacer con attempt_count 0 y max_attempts 3, y tiene attempt_count ' || v_intentos || ' y max_attempts ' || v_tope);
    END IF;

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 2 (AC-AVI-02): el reintento con la MISMA notification_key es rechazado.
    -- El notification_id es nuevo y distinto, de modo que lo unico que colisiona es la clave
    -- de negocio. El bloque anidado captura la violacion para poder examinar su SQLCODE.
    -- -------------------------------------------------------------------------------------
    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso_2 FROM dual;

    BEGIN
        INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                                  recipient_user_id, recipient_email, subject, body_text)
             VALUES (v_aviso_2, c_clave, 'CREDENTIAL_ISSUED',
                     v_usuario, c_correo, c_asunto, c_cuerpo);
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode <> -1 THEN
        RAISE_APPLICATION_ERROR(-20991, 'ORACULO TSK-057: el segundo INSERT con la misma notification_key NO fue rechazado con ORA-00001 (SQLCODE=' || v_sqlcode || '): la idempotencia del reintento no esta garantizada');
    END IF;

    -- El despachador tiene que seguir teniendo EXACTAMENTE un aviso que entregar.
    SELECT COUNT(*) INTO v_filas FROM aviso_correo WHERE notification_key = c_clave;
    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20991, 'ORACULO TSK-057 / AC-AVI-02: tras el reintento deberia quedar exactamente 1 aviso con esa notification_key y hay ' || v_filas);
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_usuario  NUMBER;
    v_aviso    VARCHAR2(36 CHAR);
    v_status   VARCHAR2(20 CHAR);
    v_error    VARCHAR2(50 CHAR);
    v_message  VARCHAR2(255 CHAR);
    v_filas    NUMBER := 0;
    v_sqlcode  NUMBER := 0;

    c_clave   CONSTANT VARCHAR2(120 CHAR) := 'ORACULO-TSK057|TERMINAL|1';
    c_nombre  CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-057 Entregado';
    c_correo  CONSTANT VARCHAR2(254 CHAR) := 'oraculo.tsk057.terminal@example.invalid';
    c_asunto  CONSTANT VARCHAR2(255 CHAR) := 'Credencial emitida (oraculo TSK-057)';
    c_cuerpo  CONSTANT VARCHAR2(200 CHAR) := 'Cuerpo congelado del oraculo TSK-057.';
    c_message CONSTANT VARCHAR2(255 CHAR) := '<oraculo-tsk057@mapfre.invalid>';

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    -- Mismo patron para las tres salidas prohibidas: bloque anidado que intenta la transicion,
    -- captura el SQLCODE y exige que sea exactamente -20060. Se comprueba el codigo numerico para
    -- que el oraculo no se conforme con "fallo algo". El UPDATE arrastra ademas un last_error_code,
    -- que es lo que despues permite comprobar que el rechazo no dejo rastro en la fila.
    PROCEDURE exigir_rechazo(p_destino VARCHAR2) IS
    BEGIN
        v_sqlcode := 0;
        BEGIN
            UPDATE aviso_correo
               SET status          = p_destino,
                   last_error_code = 'TRANSIENT_ERROR'
             WHERE notification_id = v_aviso;
        EXCEPTION
            WHEN OTHERS THEN
                v_sqlcode := SQLCODE;
        END;

        IF v_sqlcode <> -20060 THEN
            RAISE_APPLICATION_ERROR(-20992, 'ORACULO TSK-057: el UPDATE de ENVIADO a ' || p_destino || ' NO fue rechazado con ORA-20060 (SQLCODE=' || v_sqlcode || '): el estado ENVIADO no es terminal');
        END IF;
    END exigir_rechazo;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 972);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_nombre, c_correo, 'oraculo.tsk057.terminal', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk057-terminal', 'argon2id')
      RETURNING user_id INTO v_usuario;

    SELECT LOWER(RAWTOHEX(SYS_GUID())) INTO v_aviso FROM dual;

    -- Aviso YA ENTREGADO. ck_aviso_correo_enviado exige message_id y sent_at en ENVIADO, de modo
    -- que el escenario no puede montarse sin ellos.
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, body_text,
                              status, attempt_count, message_id, sent_at)
         VALUES (v_aviso, c_clave, 'CREDENTIAL_ISSUED',
                 v_usuario, c_correo, c_asunto, c_cuerpo,
                 'ENVIADO', 1, c_message, SYS_EXTRACT_UTC(SYSTIMESTAMP));

    -- -------------------------------------------------------------------------------------
    -- Comprobacion 1 (REQ-142 regla 2 / AC-SMTP-02): ninguna salida de ENVIADO esta permitida,
    -- ni a los estados de fallo ni de vuelta a la cola (AC-AVI-06 / AC-SMTP-09)
    -- -------------------------------------------------------------------------------------
    exigir_rechazo('FALLIDO');
    exigir_rechazo('DESCARTADO');
    exigir_rechazo('PENDIENTE');

    -- -------------------------------------------------------------------------------
    -- Comprobacion 2: el rechazo es atomico y la fila entregada quedo intacta
    -- -------------------------------------------------------------------------------
    SELECT status, last_error_code, message_id
      INTO v_status, v_error, v_message
      FROM aviso_correo
     WHERE notification_id = v_aviso;

    IF v_status <> 'ENVIADO' OR v_error IS NOT NULL OR v_message <> c_message THEN
        RAISE_APPLICATION_ERROR(-20993, 'ORACULO TSK-057: el aviso ENVIADO quedo alterado tras el UPDATE rechazado');
    END IF;

    -- ------------------------------------------------------------------------------------
    -- Comprobacion 3: el trigger no es un candado global. El UPDATE que NO cambia de estado
    -- (el que registra el reenvio sobre una fila ya entregada) tiene que pasar.
    -- ------------------------------------------------------------------------------------
    BEGIN
        UPDATE aviso_correo
           SET resent_at = SYS_EXTRACT_UTC(SYSTIMESTAMP)
         WHERE notification_id = v_aviso;
        v_filas := SQL%ROWCOUNT;
    EXCEPTION
        WHEN OTHERS THEN
            v_filas := -1;
    END;

    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20993, 'ORACULO TSK-057: el trigger de estado terminal bloquea un UPDATE que no cambia de estado');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
